#!/usr/bin/env python3
"""Safely extract data fields from an untrusted pickle WITHOUT unpickling.

Replays only a whitelist of safe structural opcodes onto a manual stack.
Any executable opcode (REDUCE, GLOBAL, STACK_GLOBAL, NEWOBJ*, BUILD, INST*,
EXT, OBJ, ...) causes an immediate refusal -- the file is quarantined, not
loaded.
"""
import json
import pickletools
import sys

data = open("incoming/model.pkl", "rb").read()

MARK = object()

class QuarantinedPayload:
    """Sentinel standing in for an executable pickle construct we refuse to run."""
    def __init__(self, opname, pos):
        self.opname, self.pos = opname, pos
    def __repr__(self):
        return f"<QUARANTINED {self.opname} @ offset {self.pos}>"

EXECUTABLE = {
    "REDUCE", "GLOBAL", "STACK_GLOBAL", "INST", "SHORT_BININST", "LONG_BININST",
    "NEWOBJ", "NEWOBJ_EX", "OBJ", "OBJ_MARK", "EXT", "BUILD", "NEXT_BUFFER",
}

# opcodes that only push literals / build plain containers
PUSH = {
    "SHORT_BINUNICODE", "BINUNICODE", "BINBYTES", "SHORT_BINBYTES",
    "BININT1", "BININT2", "BININT", "LONG1", "LONG4", "LONG_BINPUT",
    "BINFLOAT", "NONE", "NEWFALSE", "NEWTRUE", "BINPERSID",
}
CONTAINER = {
    "EMPTY_DICT": dict, "EMPTY_LIST": list, "EMPTY_SET": set,
}
SKIP = {"PROTO", "FRAME", "MEMOIZE", "STOP"}

stack = []
result = None
for op, arg, pos in pickletools.genops(data):
    name = op.name
    if name in SKIP:
        continue
    if name == "MARK":
        stack.append(MARK)
    elif name in PUSH:
        stack.append(arg)
    elif name in CONTAINER:
        stack.append(CONTAINER[name]())
    elif name == "SETITEM":
        val, key = stack.pop(), stack.pop()
        stack[-1][key] = val
    elif name == "SETITEMS":
        pairs = []
        while stack[-1] is not MARK:
            v, k = stack.pop(), stack.pop()
            pairs.append((k, v))
        stack.pop()  # MARK
        stack[-1].update(pairs)
    elif name == "APPEND":
        stack[-2].append(stack.pop())
    elif name == "APPENDS":
        items = []
        while stack[-1] is not MARK:
            items.append(stack.pop())
        stack.pop()  # MARK
        stack[-2].extend(items)
    elif name == "TUPLE" or name.startswith("TUPLE"):
        n = int(name[5:]) if name != "TUPLE" else len(stack)
        if name == "TUPLE":
            items = []
            while stack[-1] is not MARK:
                items.append(stack.pop())
            stack.pop()
            stack.append(tuple(items))
        else:
            stack.append(tuple(stack.pop(n)))
    elif name == "BINPUT" or name == "LONG_BINPUT":
        pass  # memo ref: value already on stack
    elif name in EXECUTABLE:
        print(f"NOTE: executable opcode {name!r} at offset {pos} -- quarantined, NOT executed", file=sys.stderr)
        stack.append(QuarantinedPayload(name, pos))
    else:
        print(f"REFUSING to process: executable/unknown opcode {name!r} at offset {pos}", file=sys.stderr)
        print(f"  The file was NOT unpickled. Quarantine it and alert the partner.", file=sys.stderr)
        sys.exit(2)

if stack:
    result = stack[0]

# ---- extract the three requested fields (pure data, no execution) ----
tensors = result["tensors"]
tensors = tensors if isinstance(tensors, list) else list(tensors)  # preserve order
inventory = {
    "model_type": result["model_type"],
    "protocol_version": result["protocol_version"],
    "tensors": tensors,
}
import os
os.makedirs("reports", exist_ok=True)
with open("reports/model_inventory.json", "w") as f:
    json.dump(inventory, f, indent=2)
    f.write("\n")
print(json.dumps(inventory, indent=2))
print("\n--- extra fields present in the pickle (for the record) ---")
print(json.dumps({k: v for k, v in result.items() if k not in ("model_type", "protocol_version", "tensors", "_load_hook")}, indent=2))
print("\nWARNING: pickle contains executable opcode(s) -- see refusal log / disassembly. Do NOT pickle.load this file.")

